def main():
    batch = sys.argv[1]
    ids = {"B22": ["YM-019","YM-020","YM-022","YM-023","YM-024","YM-025","YM-027","YM-028","YM-029","YM-030","YM-032","YM-033","YM-034","YM-035","YM-037","YM-038","YM-039","YM-040","YM-042","YM-043"],
           "B23": ["YM-044","YM-045","YM-047","YM-048","YM-049","YM-050","YM-052","YM-053","YM-054","YM-055","YM-057","YM-058","YM-059","YM-060","YM-062","YM-063","YM-064","YM-065","YM-067","YM-068"]}[batch]
    for cid in ids:
        d = P[cid]
        rec = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
               "confidence": d["confidence"], "trigger": d["trigger"]}
        p = OUT / f"{cid}.json"
        p.write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
        # self-verify
        r = json.loads(p.read_text(encoding="utf-8"))
        assert set(r) == {"case_id","prediction_text","basis","confidence","trigger"}, cid
        assert set(r["trigger"]) == {"changed_main","reserve_used","disputed","reason"}, cid
        assert r["basis"].splitlines()[0].startswith("tradition="), cid
        assert r["basis"].splitlines()[1].startswith("systems_used:"), cid
        print(cid, p.stat().st_size, r["trigger"]["changed_main"], r["trigger"]["reserve_used"], r["trigger"]["disputed"])
    print(batch, "written", len(ids))

if __name__ == "__main__":
    main()
